import { httpAjax } from './httpAjax/index.js'
import { channels } from './channels/index.js'
import initAudio from './waveAnimation/index.js';
//import './waveAnimation/index.js';
let chRoot, rootElement, loader, pauseElement, audio, hasTouch, radioStations, btnPlay, btnStop, nameElement;

hasTouch = window.matchMedia('(pointer: coarse)').matches;



pauseElement = `
<div class="pause-element">
<span>
<i class="fa-regular fa-pause"></i>
</span>
</div>`;

chRoot = `
<div class="ch">
<div class="show menu-icon">
<i class="fa-solid fa-bars"></i>
</div>
<div class="hide menu-icon">
<i class="fa-solid fa-xmark"></i>
</div>
</div>`


audio = new Audio();
const mainPromise = new Promise((resolve, reject) => resolve(channels));
mainPromise
    .then(data => {
        let completeData = data[2];
        audio.crossOrigin = 'anonymous';
        audio.src = completeData.url
        nameElement = document.querySelector('.name')
        btnPlay = document.querySelector('.btn-play')
        nameElement.innerHTML = completeData.name
        return btnPlay;
    })
    .then(data => {
        data.addEventListener('click', () => {
            audio.play()
            initAudio(audio);
        })
        btnStop = document.querySelector('.btn-stop')
        return btnStop;
    })
    .then(data => {
        data.addEventListener('click', () => {
            audio.pause()
        })
    })
    .catch(error => {
        console.log(error);

    })
    .finally(() => {
        loader = document.querySelector('.loader')
        loader.remove()
    })


const fullscreenBtn = document.getElementById('fullscreen-btn');

fullscreenBtn.addEventListener('click', async () => {
    try {
        if (document.fullscreenElement) {
            await document.exitFullscreen();
        } else {
            await document.documentElement.requestFullscreen();
        }
    } catch (error) {
        console.error('Error Full Screen:', error);
    }
});

document.addEventListener('fullscreenchange', () => {
    fullscreenBtn.textContent = document.fullscreenElement
        ? 'Out Full Screen'
        : 'Full Screen';
});